/* global __dirname */
// Bundle Leaflet locally: Expo Go must not download executable map code from a CDN.
const fs = require("node:fs");
const path = require("node:path");
const root = path.dirname(require.resolve("leaflet/package.json"));
const license = fs.readFileSync(path.join(root, "LICENSE"), "utf8");
const javascript = `/* ${license} */\n${fs.readFileSync(path.join(root, "dist/leaflet.js"), "utf8")}`;
const css = fs.readFileSync(path.join(root, "dist/leaflet.css"), "utf8");
fs.writeFileSync(path.join(__dirname, "../src/maps/leafletRuntime.generated.ts"),
  "// Generated by scripts/prepare-map-assets.cjs from the pinned Leaflet package.\n"
  + `export const LEAFLET_JS = ${JSON.stringify(javascript)};\nexport const LEAFLET_CSS = ${JSON.stringify(css)};\n`);
